BEGIN;
CREATE SCHEMA registry_test;CREATE FUNCTION registry_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;GRANT USAGE ON SCHEMA registry_test TO authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA registry_test TO authenticated;
INSERT INTO auth.users(id,email) VALUES('2c000000-0000-4000-8000-000000000001','registry@example.invalid');INSERT INTO public.companies(id,nome,created_by) VALUES('1c000000-0000-4000-8000-000000000001','Registry fixture','2c000000-0000-4000-8000-000000000001'),('1c000000-0000-4000-8000-000000000002','Other fixture','2c000000-0000-4000-8000-000000000001');INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) VALUES('1c000000-0000-4000-8000-000000000001','2c000000-0000-4000-8000-000000000001','administrador','admin_empresa','2c000000-0000-4000-8000-000000000001');
SELECT set_config('request.jwt.claim.sub','2c000000-0000-4000-8000-000000000001',true);SET LOCAL ROLE authenticated;
INSERT INTO public.motoristas(id,company_id,nome,cnh,validade_cnh,telefone,telefone_emergencia,validade_nr20,observacoes) VALUES('2c000000-0000-4000-8000-000000000002','1c000000-0000-4000-8000-000000000001','Registry driver','12345678901','2028-12-31','11987654321','11976543210','2028-01-10','Actual entered notes');
INSERT INTO public.veiculos(id,company_id,placa,tipo,marca_modelo,prefixo,motorista_telefone) VALUES('3c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000001','RGL0001','caminhao','Registry vehicle','R-1','11987654321');
SELECT registry_test.assert((SELECT telefone_emergencia='11976543210' AND validade_nr20='2028-01-10' AND validade_nr35 IS NULL FROM public.motoristas WHERE id='2c000000-0000-4000-8000-000000000002'),'all supplied driver fields persist without invented dates');
SELECT registry_test.assert(public.maintenance_vehicle_command('1c000000-0000-4000-8000-000000000001','options','{}')->'drivers'->0->>'telefone'='11987654321','options retain real driver contact');
SELECT registry_test.assert(public.maintenance_vehicle_command('1c000000-0000-4000-8000-000000000001','options','{}')->'vehicles'->0->>'marca_modelo'='Registry vehicle','options retain real vehicle data');
SELECT registry_test.assert((SELECT count(*)=0 FROM public.motoristas WHERE company_id='1c000000-0000-4000-8000-000000000002'),'tenant isolation');
INSERT INTO public.maintenance_partners(id,company_id,razao_social) VALUES('4c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000001','Registry workshop');
SELECT set_config('registry_test.order',public.maintenance_order_command('1c000000-0000-4000-8000-000000000001','create','{"vehicle_id":"3c000000-0000-4000-8000-000000000001","partner_id":"4c000000-0000-4000-8000-000000000001","driver_id":"2c000000-0000-4000-8000-000000000002","tipo":"corretiva","prioridade":"media","descricao_problema":"Real registry OS","km_abertura":0}')->>'id',true);
SELECT registry_test.assert(NOT(public.maintenance_order_dispatch('1c000000-0000-4000-8000-000000000001','document',jsonb_build_object('id',current_setting('registry_test.order')))->'vehicle' ? 'renavam'),'RENAVAM removed from document payload');
INSERT INTO public.motoristas(id,company_id,nome,cnh,validade_cnh) VALUES('2c000000-0000-4000-8000-000000000003','1c000000-0000-4000-8000-000000000001','Delete fixture','10987654321','2028-12-31');DELETE FROM public.motoristas WHERE id='2c000000-0000-4000-8000-000000000003' AND company_id='1c000000-0000-4000-8000-000000000001';SELECT registry_test.assert(NOT EXISTS(SELECT 1 FROM public.motoristas WHERE id='2c000000-0000-4000-8000-000000000003'),'delete remains deleted');
RESET ROLE;ROLLBACK;
